<script lang="ts">
 import {groupEvidenceSports,topMarket} from '#lib/evidence-groups.js';
 import {app} from '#lib/state.svelte.ts';import {evidenceSlipPick} from '#lib/evidence-slip.js';
 import {onMount,onDestroy,untrack} from 'svelte';import {anyApi} from 'convex/server';
 import {auth} from '#lib/auth.svelte.ts';import {feed} from '#lib/feed.svelte.ts';
 import {startEvidenceRefresh} from '#lib/evidence-refresh.js';
 import {evidenceShortlist,evidenceCatalogIsFresh} from '#lib/evidence-shortlist.js';import {pct,odds} from '#lib/format.ts';import {SPORTS,SPORT_ORDER} from '#lib/sports.ts';
 let allowed=$state(false),checked=$state(false),loading=$state(false),error=$state(''),report=$state<any>(null),checkedAt=$state(0),now=$state(Date.now());
 let scope=$state('all');let opened=$state<Record<string,boolean>>({});
 let minModel=$state(55),minSamples=$state(20),minStrike=$state(60),minFloor=$state(50),sameLeague=$state(false),sport=$state('all'),kind=$state('all'),search=$state(''),hours=$state(168),shown=$state<Record<string,number>>({});
 let etag='',controller:AbortController|undefined,disposed=false,reloadQueued=false;
 const date=(v:number)=>new Date(v).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'});
 $effect(()=>{const client=auth.client;allowed=false;checked=!client;if(!client)return;return client.onUpdate(anyApi.admin.status,{},r=>{allowed=r?.isSuperAdmin===true;checked=true;},()=>{error='Administrator access could not be verified.';checked=true;});});
 $effect(()=>{const client=auth.client;if(!allowed||!client){controller?.abort();report=null;etag='';return;}return client.onUpdate(anyApi.evidence.meta,{},meta=>untrack(()=>{if(!meta){void load();return;}if(report&&etag===`"${meta.version}"`){checkedAt=meta.updatedAt;now=Date.now();}else void load();}),()=>{error='Evidence updates disconnected. Automatic retry remains active.';});});
 onMount(()=>startEvidenceRefresh({refresh:load,canRefresh:()=>allowed&&!loading,onTick:()=>now=Date.now()}));onDestroy(()=>{disposed=true;controller?.abort();});
 async function load(){if(!allowed||disposed)return;if(loading){reloadQueued=true;return;}loading=true;error='';const request=controller=new AbortController(),timeout=setTimeout(()=>request.abort(),20000);try{
  const response=await fetch('/api/admin/evidence',{headers:etag?{'If-None-Match':etag}:{},cache:'no-store',signal:controller.signal});
  if(disposed||!allowed||request.signal.aborted)return;now=Date.now();
  if(response.status===304&&report){checkedAt=Number(response.headers.get('X-Evidence-Checked-At'))||checkedAt;return;}
  if(!response.ok)throw Error(`Evidence catalog could not load (HTTP ${response.status}). Retained results are not replaced with estimates.`);
  let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());
  if(bytes.length>64*1024*1024)throw Error('Evidence catalog exceeds the display budget.');const data=JSON.parse(new TextDecoder().decode(bytes));if(data.schema!==1||!Array.isArray(data.upcoming)||!data.groups)throw Error('Evidence catalog format is not supported.');
  if(disposed||!allowed||request.signal.aborted)return;report=data;etag=response.headers.get('ETag')??'';checkedAt=Number(response.headers.get('X-Evidence-Checked-At'))||data.generatedAt;now=Date.now();
 }catch(reason){if(!disposed&&allowed)error=request.signal.aborted?'Evidence request timed out. Automatic retry is active.':(reason as Error).message;}finally{clearTimeout(timeout);loading=false;if(reloadQueued&&!disposed&&allowed){reloadQueued=false;void load();}}}
 const valid=$derived([minModel,minSamples,minStrike,minFloor,hours].every(Number.isFinite)&&minModel>=55&&minModel<=100&&minSamples>=1&&minSamples<=100000&&Number.isInteger(minSamples)&&minStrike>=0&&minStrike<=100&&minFloor>=0&&minFloor<=100&&hours>=1);
 const stale=$derived(!evidenceCatalogIsFresh(checkedAt,now));
 const games=$derived(new Map((feed.data?.games??[]).map(g=>[g.id,g])));
 const result=$derived(valid&&report?evidenceShortlist(report,{minModel:minModel/100,minSamples,minStrike:minStrike/100,minFloor:minFloor/100,sameLeague,sport,kind,scope,search,hours,includePeriodForecasts:true,catalogCheckedAt:checkedAt,liveCheckedAt:Date.parse(feed.data?.generatedAt??'')},now,games):{rows:[],rejected:{}});
 const sections=$derived([{title:'Top markets',top:true,sports:groupEvidenceSports(result.rows.filter(topMarket))},{title:'Other markets',top:false,sports:groupEvidenceSports(result.rows.filter((r:any)=>!topMarket(r)))}].filter(s=>s.sports.length));
 const sportGroups=$derived(sections.flatMap(s=>s.sports));
 const groups=$derived(sportGroups.flatMap(s=>s.markets));
 const fixtures=$derived(new Set(result.rows.map((r:any)=>r.fixtureId)).size);
 function choose(row:any){if(!allowed)return;if(app.inSlip(row.id)){app.remove(row.id);return;}const game=app.gameById(row.fixtureId),current=app.byId(row.fixtureId)?.markets.flatMap(g=>g.selections).find(s=>s.id===row.id),pick=evidenceSlipPick(row,game,current,result.rows.filter((r:any)=>r.fixtureId===row.fixtureId),Date.now());if(!pick){error='This fixture is no longer available before kickoff. Refresh the evidence and fixture board.';return;}if(!app.toggle(pick as any))error='The fixture changed before this selection could be added.';}
 function reset(){minModel=55;minSamples=20;minStrike=60;minFloor=50;sameLeague=false;sport='all';kind='all';scope='all';search='';hours=168;shown={};}
 async function proof(fixtureId:string){if(!auth.client)return;try{const meta=await auth.client.query(anyApi.performance.archive,{fixtureId});if(!meta?.url)throw Error('The original archive is not available.');const response=await fetch(meta.url);if(!response.ok)throw Error('The original archive could not load.');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=`${fixtureId}-published-evidence.gz`;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch(reason){error=(reason as Error).message;}}
</script>
<svelte:head><title>Evidence shortlist — PuntersEdge administration</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<section class="min-w-0 space-y-5">
 <header class="surface relative overflow-hidden p-5 sm:p-7"><div class="pointer-events-none absolute -right-12 -top-12 h-44 w-44 rounded-full bg-model/10 blur-3xl" aria-hidden="true"></div><p class="text-xs font-semibold uppercase tracking-[.18em] text-model">🌡️ Production-ledger intelligence</p><div class="mt-3 flex flex-wrap items-start justify-between gap-4"><div class="min-w-0"><h1 class="text-3xl font-bold sm:text-4xl">Evidence shortlist</h1><p class="mt-3 max-w-3xl text-sm leading-relaxed text-haze">Upcoming published selections and supported period forecasts. Grouped by sport and market, ranked from highest to lowest published Model %. Each fixture keeps its related lines together, with separate evidence and betslip controls for every option.</p></div><button class="evidence-action action-slip" onclick={()=>app.slipOpen=true}>🧾 Open betslip · {app.slip.length}</button><a class="evidence-action action-history" href="/admin/evidence/history">📜 Evidence history</a><button class="evidence-action action-refresh" disabled={!allowed||loading} onclick={load}>{loading?'Refreshing…':'Refresh evidence'}</button></div>{#if checkedAt}<p class="mt-4 text-xs text-haze">Pipeline checked {date(checkedAt)} WAT · Original published Model %, independent of personal model settings.</p>{/if}</header>
 {#if error}<div class="surface border-loss/50 p-4" role="alert"><strong class="text-loss">Evidence could not refresh</strong><p class="mt-2 break-words text-sm">{error}</p><button class="btn-secondary mt-3" disabled={loading} onclick={load}>Retry</button></div>{/if}
 {#if !checked}<div class="workspace-state" role="status"><h2>Verifying administrator access</h2></div>{:else if !allowed}<div class="workspace-state"><h2>Administrator access required</h2><p>This shortlist and its historical evidence are private.</p><a class="btn-primary mt-4" href="/login?next=%2Fadmin%2Fevidence">Sign in</a></div>{:else}
 <details class="surface p-4 sm:p-5"><summary class="min-h-11 cursor-pointer py-2 text-lg font-bold">Selection rules</summary><div class="flex flex-wrap items-center justify-between gap-3"><button class="evidence-action action-reset" onclick={reset}>Reset rules</button></div><div class="mt-4 grid min-w-0 gap-3 sm:grid-cols-2 xl:grid-cols-4">
 <label class="grid min-w-0 gap-1 text-xs text-haze">Sport<select class="rule-input" bind:value={sport}><option value="all">All supported sports</option>{#each SPORT_ORDER as s}<option value={s}>{SPORTS[s].label}</option>{/each}</select></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Period<select class="rule-input" bind:value={scope}><option value="all">All supported periods</option><option value="full">Full match</option><option value="first_half">First half</option><option value="first_quarter">First quarter</option><option value="regulation">Regulation</option><option value="first_period">First period</option></select></label><label class="grid min-w-0 gap-1 text-xs text-haze">Market family<select class="rule-input" bind:value={kind}><option value="all">All market families</option><option value="winner">Home / away / draw</option><option value="double-chance">Double chance · all</option><option value="dc1x">Home or draw · 1X</option><option value="dcx2">Away or draw · X2</option><option value="dc12">Home or away · 12</option><option value="team-15">Team over 1.5 goals · football</option><option value="team-05">Team over 0.5 goals · football</option><option value="bttsYes">Both teams to score · Yes · football</option><option value="bttsNo">Both teams to score · No · football</option><option value="first-half-u15">First half Under 1.5 goals · football</option><option value="first-half-u25">First half Under 2.5 goals · football</option><option value="basketball-winner">Basketball / NBA · match winner</option><option value="basketball-spread">Basketball / NBA · spread</option><option value="basketball-total">Basketball / NBA · match total Over / Under</option><option value="basketball-team-over">Basketball / NBA · team total Over</option><option value="basketball-team-under">Basketball / NBA · team total Under</option><option value="basketball-team">Basketball team points · Over / Under</option><option value="match-over">Match totals · Over</option><option value="match-under">Match totals · Under</option><option value="two-consecutive">Team to score two consecutive goals</option><option value="corners">Football corners · Over / Under</option><option value="first-score">First team to score · coverage check</option><option value="match-total">Match Over / Under</option><option value="team-home">Home team Over / Under</option><option value="team-away">Away team Over / Under</option><option value="handicap">Handicap / spread</option><option value="other">Other supported markets</option></select></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum Model %<input class="rule-input" type="number" min="55" max="100" bind:value={minModel} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum comparable fixtures<input class="rule-input" type="number" min="1" max="100000" step="1" bind:value={minSamples} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum historical strike %<input class="rule-input" type="number" min="0" max="100" bind:value={minStrike} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum 95% win-rate floor %<input class="rule-input" type="number" min="0" max="100" bind:value={minFloor} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Kickoff window<select class="rule-input" bind:value={hours}>{#each [1,3,6,12,24,48,72,168] as h}<option value={h}>{h<168?`Next ${h} hours`:'Next 7 days'}</option>{/each}</select></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Fixture / competition / country<input class="rule-input" type="search" bind:value={search} placeholder="Search fixtures or leagues" /></label>
 </div><label class="mt-4 flex min-h-11 items-center gap-3 text-sm"><input type="checkbox" bind:checked={sameLeague} /> Use the same league only</label><p class="mt-2 text-xs leading-relaxed text-haze">Comparable means the same sport, exact outcome and line, period, engine/model version, input-source class and 10-point Model % band. Without the league rule, the pool spans leagues in that sport. This is a defined similarity screen, not a claim that every match circumstance is identical.</p>{#if !valid}<p class="mt-3 text-sm text-loss" role="alert">Enter valid percentages and a positive whole-number sample requirement.</p>{/if}</details>
 {#if loading&&!report}<div class="workspace-state" role="status"><h2>Loading retained evidence</h2><p>Preparing the protected production-ledger catalog.</p></div>{:else if report}
 <div class="grid grid-cols-2 gap-3 lg:grid-cols-4">{#each [['Shortlisted options',result.rows.length],['Distinct fixtures',fixtures],['Market groups',groups.length],['Historical fixtures',report.historicalFixtures]] as [label,value]}<div class="surface min-w-0 p-4"><p class="text-xs text-haze">{label}</p><p class="mt-2 text-2xl font-bold">{value}</p></div>{/each}</div>
 {#if stale}<div class="workspace-state"><h2>Waiting for a newer evidence catalog</h2><p>The scheduled pipeline is delayed. Future published forecasts remain available below. Past fixtures with stale status are hidden; verified final results remain in history. Automatic retry is active.</p></div>{/if}
 {#if report.coverage?.missingArchives}<p class="surface p-4 text-sm text-book">{report.coverage.missingArchives} retained archives were unavailable. Counts below describe only the evidence actually read.</p>{/if}
 {#if !result.rows.length}<div class="workspace-state"><h2>No upcoming options meet every rule</h2>{#if kind==='corners'}<p class="mt-3 text-sm text-book">Corner collection and chronological training are enabled. Recommendations require sufficient pre-match team histories and a validated model for this league. Missing corners are never treated as zero; extra-time statistics are excluded.</p>{/if}{#if kind==='two-consecutive'}<p class="mt-3 text-sm text-book">Home and away are separate selections. Two consecutive goals means the same team scores twice with no opponent goal between, at any point in regulation time including stoppage time. Extra time and shootouts are excluded. Only forecasts passing chronological league validation can publish. The current rules have no matching validated forecasts and verified goal sequences; team Over 1.5 results cannot substitute for this evidence. No picks or favourable ratings are invented.</p>{/if}{#if kind==='first-score'}<p class="mt-3 text-sm text-book">First-team-to-score is not enabled in this evidence screen: the ledger needs published first-scorer predictions and verified goal-event outcomes. Final scores cannot identify who scored first. No first-scorer history or confidence is fabricated.</p>{/if}<p>Nothing is invented or awarded a green meter to fill the table. There are {report.upcoming.length} published upcoming fixtures in the catalog.</p><p class="mt-3 text-sm">Excluded options: {Object.entries(result.rejected).map(([key,value])=>`${key.replace(/([A-Z])/g,' $1').toLowerCase()}: ${value}`).join(' · ')}</p><p class="mt-3 text-sm">A new model version, exact line or probability band may need more settled fixtures. Adjust the visible thresholds to inspect a broader evidence pool.</p></div>{/if}
 <details class="surface p-4"><summary class="min-h-11 cursor-pointer py-3 font-bold">🟡 Scoring market assessment · archived predictions</summary><p class="mt-2 text-sm text-haze">Automatic comparison of frozen probabilities with verified results. Multiple lines from one fixture are treated as a block. Yellow identifies these market families, not a guaranteed win or validated betting edge.</p>{#if report?.scoringAssessment}<p class="mt-2 text-xs text-haze">{report.scoringAssessment.coverage.firstHalfEventMarkets}</p><div class="mt-3 grid gap-3 md:grid-cols-2">{#each report.scoringAssessment.segments as segment}<article class="rounded-xl border border-line p-3"><h3 class="font-bold">{segment.sport} · {segment.scope.replaceAll('_',' ')} · {segment.family}</h3><p class="mt-1 break-words text-xs text-haze">{segment.artifact} · {segment.source}</p><p class="mt-2 text-sm">{segment.nFixtures} distinct fixtures · {segment.trainN} earlier / {segment.testN} later</p><p class="mt-2 text-xs text-haze">Published / candidate Brier: {segment.publishedBrier?.toFixed(4)??'Unavailable'} / {segment.candidateBrier?.toFixed(4)??'Unavailable'}</p><p class="mt-2 text-sm">{segment.status}</p><p class="mt-1 text-xs text-haze">{segment.reasons.join(' · ')}</p></article>{/each}</div>{:else}<p class="mt-3 text-sm text-haze">Assessment will appear after the next catalog refresh.</p>{/if}</details>
<div class="space-y-9">{#each sections as section (section.title)}<section class="space-y-5" aria-label={section.title}><h2 class="rounded-2xl border p-4 text-2xl font-bold" class:top-heading={section.top}>{section.title}</h2>{#if section.top}<p class="text-sm text-haze">Basketball/NBA supported full-game, first-half and first-quarter scoring forecasts across available leagues enter automatically at Model 55% or above without sample, strike-rate or confidence-floor thresholds. Every shortlist market has a hard 55% Model floor. Sport, period, market, search and kickoff-window filters still apply. Forecast-only rows are not historically validated recommendations.</p>{/if}{#each section.sports as category (category.sport)}<section class="min-w-0 space-y-3" aria-label={SPORTS[category.sport as keyof typeof SPORTS]?.label??category.sport}><header class="flex flex-wrap items-center justify-between gap-2 px-1"><h2 class="text-2xl font-bold">{SPORTS[category.sport as keyof typeof SPORTS]?.emoji} {SPORTS[category.sport as keyof typeof SPORTS]?.label??category.sport}</h2><span class="text-xs text-haze">{category.markets.length} markets · {category.count} shortlisted options</span></header>
 {#each category.markets as market (market.key)}<details ontoggle={(event)=>{opened[market.key]=event.currentTarget.open;}} class="market-group surface min-w-0 overflow-hidden" data-sport={category.sport} data-focus={section.top?'scoring':undefined}><summary class="market-summary flex min-h-14 cursor-pointer flex-wrap items-center justify-between gap-3 p-4 sm:p-5"><div class="min-w-0"><h3 class="break-words text-lg font-bold capitalize">{market.title}</h3><p class="mt-1 text-xs text-haze">{market.count} options · {market.fixtures.length} fixtures · highest Model % first</p></div><span class="rounded-full bg-model/10 px-3 py-1 text-xs font-semibold text-model">{pct(market.best,1)} highest Model</span><span class="market-chevron text-haze" aria-hidden="true">⌄</span></summary>
 {#if opened[market.key]}<div class="space-y-4 border-t border-line p-3 sm:p-4">{#each market.fixtures.slice(0,shown[market.key]??30) as fixture,index (fixture.fixtureId)}<article class="fixture-evidence min-w-0 overflow-hidden rounded-2xl border border-line bg-ink/50"><header class="flex flex-wrap items-start justify-between gap-3 p-4"><div class="min-w-0"><a class="fixture-name break-words font-semibold hover:underline" href="/match?id={encodeURIComponent(fixture.fixtureId)}">#{index+1} · {fixture.matchTitle}</a><p class="mt-2 text-xs text-haze">{fixture.league}{#if fixture.tournament&&fixture.tournament!==fixture.league} · {fixture.tournament}{/if}{#if fixture.country} · {fixture.country}{/if}</p><p class="mt-1 text-xs text-haze">{date(fixture.kickoff)} WAT · {fixture.options.length} shortlisted option{fixture.options.length===1?'':'s'}</p></div></header><p class="px-4 pb-2 text-xs text-haze sm:hidden">Swipe the options table to view every metric →</p><div class="max-w-full overflow-x-auto overscroll-x-contain"><table class="evidence-table"><caption class="sr-only">{fixture.matchTitle} · {market.title} ranked selections</caption><thead><tr><th>Published selection</th><th>Model %</th><th>Recurrence & proof</th><th>Confidence meter</th><th>Recorded price & betslip</th></tr></thead><tbody>{#each fixture.options as r (r.id)}<tr><td><strong class={r.side==='home'||r.kind==='team-home'?'side-home':r.side==='away'||r.kind==='team-away'?'side-away':'text-chalk'}>{r.selection}</strong><p class="mt-2 text-xs text-haze">{r.scope.replaceAll('_',' ')} · Model band {r.probabilityBand*10}–{(r.probabilityBand+1)*10}%</p><p class="mt-1 break-all text-[11px] text-haze">{r.artifact}</p></td><td class="text-lg font-bold text-model">{pct(r.modelProb,1)}</td><td><strong class="text-lg">{r.cohort.binaryN?pct(r.cohort.strikeRate,1):'No recorded recurrence'}</strong>{#if r.evidenceTier==='forecast-only'}<p class="mt-2 font-semibold text-book">Forecast only · historical screening suspended</p>{/if}<p class="mt-1 text-xs text-haze">{r.cohort.won} wins / {r.cohort.binaryN} binary results</p><p class="mt-1 text-xs text-haze">{r.cohort.lost} lost · {r.cohort.push} returned · {r.cohort.partial} partial</p><p class="mt-1 text-xs text-haze">Quoted history ROI: {r.cohort.quotedRoi===null?'Unavailable':(r.cohort.quotedRoi*100).toFixed(1)+'%'} · {r.cohort.quotedN} quotes</p><details class="mt-2 text-xs"><summary class="min-h-11 cursor-pointer py-3 font-semibold text-pop">Recorded examples & rules</summary><div class="max-w-80 space-y-3 rounded-xl border border-line bg-ink p-3"><p>Pool: {sameLeague?r.league:'same sport across leagues'} · {r.source}. One observation per fixture and exact outcome. Returned and partial stakes are excluded from binary strike rate.</p>{#each r.cohort.examples as example}<div class="border-t border-line pt-2"><strong>{example.matchTitle}</strong><p>{example.league}{example.country?' · '+example.country:''}</p><p>{example.selection} · Model {pct(example.modelProb,1)} · {example.result}</p><p>{date(example.kickoff)} · Final {example.score.home}–{example.score.away}{#if example.score.regHome!==undefined&&example.score.regAway!==undefined&&(example.score.regHome!==example.score.home||example.score.regAway!==example.score.away)} (regulation {example.score.regHome}–{example.score.regAway}){/if}</p><button class="min-h-11 font-semibold text-model underline" onclick={()=>proof(example.fixtureId)}>Download original publication</button></div>{/each}<p>The latest five retained examples are shown; the count covers the full matching cohort.</p></div></details></td><td>{#if r.cohort.binaryN}<strong>{pct(r.cohort.interval.low,1)}</strong><div class="mt-2 h-2.5 w-36 overflow-hidden rounded-full bg-line" role="meter" aria-label="95% historical win-rate lower bound" aria-valuemin="0" aria-valuemax="100" aria-valuenow={Number((r.cohort.interval.low*100).toFixed(1))}><div class="h-full rounded-full transition-[width] duration-300" style:width={`${r.cohort.interval.low*100}%`} style:background={r.cohort.interval.low>=.65?'#22c55e':r.cohort.interval.low>=.5?'#f59e0b':'#ef4444'}></div></div><p class="mt-2 text-xs font-semibold">{r.cohort.interval.low>=.65?'Strong recurrence':r.cohort.interval.low>=.5?'Moderate recurrence':'Weak recurrence'}</p><p class="mt-2 text-xs text-haze">95% Wilson interval<br />{pct(r.cohort.interval.low,1)}–{pct(r.cohort.interval.high,1)}</p><p class="mt-1 text-[11px] text-haze">Historical floor, not fixture win probability.</p>{:else}<strong class="text-book">Not validated</strong><p class="mt-2 text-xs text-haze">No historical confidence meter is available. Model % is the original forecast estimate.</p>{/if}</td><td><strong class="text-book">{r.odds>1?odds(r.odds):'Unpriced'}</strong><p class="mt-2 text-xs text-haze">{r.odds>1?'Published snapshot':'No bookmaker quote'}<br />{date(r.publishedAt)}</p><button class="mt-3 inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-emerald-300/50 bg-emerald-300/15 px-3 py-2 text-sm font-semibold text-model transition-colors hover:bg-emerald-300/25 disabled:opacity-40" aria-pressed={app.inSlip(r.id)} disabled={!app.gameById(r.fixtureId)} onclick={()=>choose(r)}>{app.inSlip(r.id)?'✓ Added · remove':'+ Add to betslip'}</button></td></tr>{/each}</tbody></table></div></article>{/each}
 {#if market.fixtures.length>(shown[market.key]??30)}<button class="btn-secondary" onclick={()=>shown={...shown,[market.key]:(shown[market.key]??30)+30}}>Show 30 more fixtures · {market.fixtures.length-(shown[market.key]??30)} remaining</button>{/if}</div>{/if}</details>{/each}</section>{/each}</section>{/each}</div>
 <details class="surface p-4 text-sm"><summary class="min-h-11 cursor-pointer py-3 font-semibold">How the evidence meter works</summary><div class="mt-3 space-y-3 leading-relaxed text-haze"><p>The meter is the lower end of a 95% Wilson interval for the historical win rate. It rises with a stronger observed rate and supporting sample size, and can fall when losses accumulate. Model % remains a separate pre-match estimate.</p><p>Screening many markets can select patterns that do not persist. These descriptive cohorts have not established a profitable out-of-sample strategy. Fixtures can remain related through teams, leagues and time; the interval assumes comparable independent trials.</p><p>Only outcomes with the same exact line and direction are pooled. An Over 2.5 result never supplies evidence for Over 1.5. Different fitted versions are not pooled. Quarter-line settlements remain in the production ledger but are excluded from this binary heat-meter screen. Green means a historical floor of at least65%, amber50–65%, and red below50%. Unpriced outcomes can contribute recurrence evidence; they cannot establish a quoted-price return.</p><p>Provider-confirmed finished fixtures leave the active shortlist on the next evidence refresh and are recorded in history when their verified result is available. Past kickoffs remain active only while the provider confirms live play; unconfirmed status is allowed a maximum one-hour grace after kickoff. Past fixtures are hidden when their latest status is over one hour old. Future published forecasts remain available with a data-age notice during delays. Evidence updates arrive directly when its catalog changes; the page also retries every five minutes while visible and when you return. Pipeline runs are scheduled every 30 minutes, but the runner service can delay them. All shortlisted options are counted; markets initially show 30 fixture cards for rendering performance.</p><a class="font-semibold text-model underline" href="https://www.itl.nist.gov/div898/handbook/prc/section2/prc241.htm" target="_blank" rel="noreferrer">NIST methodology for proportion confidence intervals ↗</a></div></details>
 {/if}{/if}
</section>
